package site.hsu.hub.application.adapter.out.persistence;import jakarta.persistence.*;
@Entity@Table(name="application_answers",uniqueConstraints=@UniqueConstraint(columnNames={"application_id","question_id"}))public class ApplicationAnswerEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="application_id",nullable=false)private Long applicationId;@Column(name="question_id",nullable=false)private Long questionId;@Column(name="answer_value",nullable=false,columnDefinition="LONGTEXT")private String value;protected ApplicationAnswerEntity(){}public ApplicationAnswerEntity(Long app,Long q,String value){applicationId=app;questionId=q;this.value=value;}public Long applicationId(){return applicationId;}public Long questionId(){return questionId;}public String value(){return value;}}
